PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?tsRef ?equip ?equipName ?sensorLabel WHERE {
  ?s a brick:Electric_Power_Sensor .
  ?s brick:isPointOf ?equip .
  OPTIONAL { ?equip rdfs:label ?equipName }
  ?s ref:hasExternalReference ?tsRef .
  OPTIONAL { ?s rdfs:label ?sensorLabel }
}

